package io.mark.hitsplats;

import com.google.inject.Provides;
import io.mark.hitsplats.art.HitsplatSkin;
import io.mark.hitsplats.art.HitsplatSprites;
import io.mark.hitsplats.combat.CombatStyle;
import io.mark.hitsplats.combat.CombatStyleResolver;
import io.mark.hitsplats.combat.CombatStyleTables;
import io.mark.hitsplats.config.HealSplatMode;
import io.mark.hitsplats.config.HitsplatStylesConfig;
import io.mark.hitsplats.heal.HealSource;
import io.mark.hitsplats.heal.HealTracker;
import io.mark.hitsplats.hit.HitsplatTracker;
import io.mark.hitsplats.overlay.HitsplatStylesOverlay;
import io.mark.hitsplats.overlay.NpcHeights;
import java.io.IOException;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.SpritePixels;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.api.events.ProjectileMoved;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.itemstats.ItemStatPlugin;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;

@Slf4j
@PluginDescriptor(
	name = "Hitsplat Styles",
	description = "Replaces hitsplats with art from an earlier era - 2002, 2010 or 2011",
	tags = {"hitsplat", "hitsplats", "damage", "heal", "combat", "retro", "fade", "style", "styles", "2002", "2010", "2011"},
	internalName = "hitsplat-styles"
)
@PluginDependency(ItemStatPlugin.class)
public class HitsplatStylesPlugin extends Plugin {
	public static final boolean DEBUG_SLOTS = false;

	private static final int NATIVE_HEAL_WINDOW_CYCLES = 30;
	private static final int NO_NATIVE_HEAL = Integer.MIN_VALUE;
	private static final int NATURAL_REGEN_AMOUNT = 1;

	private static final int[] SUPPORTED_HITMARK_SPRITE_IDS = {
		SpriteID.Hitmark.HITSPLAT_BLUE_MISS,
		SpriteID.Hitmark._9,
		SpriteID.Hitmark._1,
		SpriteID.Hitmark._10,
		SpriteID.Hitmark._24,
		SpriteID.Hitmark._27,
		SpriteID.Hitmark.HITSPLAT_GREEN_POISON,
		SpriteID.Hitmark.HITSPLAT_DARK_GREEN_VENOM,
		SpriteID.Hitmark._3,
		SpriteID.Hitmark._12,
		SpriteID.Hitmark._35,
		SpriteID.Hitmark.BURN_DAMAGE,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private HitsplatStylesConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HitsplatStylesOverlay overlay;

	@Inject
	private HitsplatSprites sprites;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private CombatStyleResolver combatStyleResolver;

	@Inject
	private CombatStyleTables combatStyleTables;

	@Inject
	private HitsplatTracker tracker;

	@Inject
	private HealTracker healTracker;

	@Inject
	private HealSource healSource;

	@Inject
	private NpcHeights npcHeights;

	private SpritePixels blankSprite;

	private int hitpoints = -1;
	private int pendingHeal;
	private int nativeHealCycle = NO_NATIVE_HEAL;

	@Provides
	HitsplatStylesConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(HitsplatStylesConfig.class);
	}

	@Override
	protected void startUp() {
		overlayManager.add(overlay);
		loadSprites(false);
		combatStyleTables.load();
		npcHeights.load();

		if (DEBUG_SLOTS) {
			return;
		}

		hideNativeHitsplats();

		if (client.getGameState() == GameState.LOGGED_IN) {
			queueMessage("Hitsplat Styles: log out and back in to hide the default hitsplats.");
		}
	}

	@Override
	protected void shutDown() {
		overlayManager.remove(overlay);
		tracker.clear();
		healTracker.clear();
		healSource.clear();
		hitpoints = -1;
		pendingHeal = 0;
		combatStyleResolver.clear();
		combatStyleTables.clear();
		npcHeights.clear();
		sprites.clear();
		showNativeHitsplats();
	}

	private void loadSprites(boolean announceEmpty) {
		boolean packs = config.resourcePacks();
		sprites.load(config.shadowWidth(),
			packs ? this::overrideDirectory : () -> null,
			applied -> clientThread.invokeLater(() -> announceResourcePack(packs, applied, announceEmpty)));
	}

	private void announceResourcePack(boolean packs, int applied, boolean announceEmpty) {
		if (!packs) {
			if (announceEmpty) {
				queueMessage("Hitsplat Styles: resource packs off, using the built-in art.");
			}

			return;
		}

		if (applied > 0) {
			queueMessage("Hitsplat Styles: applied " + applied
				+ (applied == 1 ? " sprite" : " sprites") + " from your resource pack.");
		} else if (announceEmpty) {
			queueMessage("Hitsplat Styles: no resource pack sprites found in plugin-data/hitsplat-styles.");
		}
	}

	private Filepath overrideDirectory() {
		try {
			return getPluginDirectory();
		} catch (IOException e) {
			log.debug("Unable to open the hitsplat override directory", e);
			return null;
		}
	}

	private void hideNativeHitsplats() {
		blankSprite = client.createSpritePixels(new int[]{0}, 1, 1);

		Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		for (int spriteId : SUPPORTED_HITMARK_SPRITE_IDS) {
			overrides.put(spriteId, blankSprite);
		}
	}

	private void showNativeHitsplats() {
		if (blankSprite == null) {
			return;
		}

		Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		for (int spriteId : SUPPORTED_HITMARK_SPRITE_IDS) {
			overrides.remove(spriteId, blankSprite);
		}

		blankSprite = null;
	}

	private void queueMessage(String message) {
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	@Subscribe
	public void onProjectileMoved(ProjectileMoved event) {
		combatStyleResolver.onProjectileMoved(event.getProjectile());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState state = event.getGameState();

		if (state == GameState.LOADING || state == GameState.LOGIN_SCREEN) {
			combatStyleResolver.clear();
			tracker.clear();
			healTracker.clear();
			healSource.clear();
			pendingHeal = 0;
		}

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING) {
			hitpoints = -1;
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event) {
		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();
		int cycle = client.getGameCycle();
		boolean local = actor == client.getLocalPlayer();

		int type = hitsplat.getHitsplatType();
		boolean block = HitsplatSkin.isBlock(type);
		HitsplatSkin skin = HitsplatSkin.isSupported(type)
			? HitsplatSkin.forType(type, local)
			: null;
		CombatStyle combatStyle = skin == null ? null
			: block ? CombatStyle.DEFENCE : combatStyleResolver.resolve(actor, cycle);

		if (log.isDebugEnabled()) {
			log.debug("Hitsplat type {} for {} on {}{}", type, hitsplat.getAmount(), actor.getName(),
				skin == null ? " - not supported, left as the game drew it" : " -> " + skin);
		}

		int slot = tracker.add(actor, cycle, hitsplat.getDisappearsOnGameCycle(), skin, combatStyle,
			String.valueOf(hitsplat.getAmount()), block);

		if (!local) {
			return;
		}

		if (type == HitsplatID.HEAL) {
			nativeHealCycle = cycle;
		}

		healTracker.vacate(slot);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!HitsplatStylesConfig.GROUP.equals(event.getGroup())) {
			return;
		}

		if (HitsplatStylesConfig.KEY_RESOURCE_PACKS.equals(event.getKey())) {
			loadSprites(true);
		} else if (HitsplatStylesConfig.KEY_SHADOW_WIDTH.equals(event.getKey())) {
			loadSprites(false);
		}

		if (!config.healSplatMode().isEnabled()) {
			healTracker.clear();
			healSource.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (config.healSplatMode().isEnabled()) {
			healSource.onMenuOptionClicked(event);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event) {
		if (event.getSkill() != Skill.HITPOINTS) {
			return;
		}

		int current = event.getBoostedLevel();
		int previous = hitpoints;
		hitpoints = current;

		if (previous > 0 && current > previous) {
			pendingHeal += current - previous;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		int healed = pendingHeal;
		pendingHeal = 0;

		HealSplatMode mode = config.healSplatMode();
		if (healed <= 0 || !mode.isEnabled()) {
			return;
		}

		int cycle = client.getGameCycle();
		if (nativeHealCycle != NO_NATIVE_HEAL && cycle - nativeHealCycle <= NATIVE_HEAL_WINDOW_CYCLES) {
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null) {
			return;
		}

		HealSource.UsedItem used = healSource.claim();
		if (used == null && healed <= NATURAL_REGEN_AMOUNT) {
			return;
		}

		int itemId = used != null && mode.isItem() ? used.getItemId() : -1;
		int amount = used != null && config.healOverheal() ? used.getRestored() : healed;

		int busySlots = tracker.busySlots(local, cycle, config.fadeOut() ? config.fadeLength() : 0);
		healTracker.add(cycle, busySlots, amount, itemId);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event) {
		tracker.remove(event.getActor());
	}

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event) {
		tracker.remove(event.getActor());
	}
}

package io.mark.hitsplats.art;

import net.runelite.api.HitsplatID;

public enum HitsplatSkin
{
	DAMAGE("damage_normal"),
	DAMAGE_TINTED("damage_tinted", "damage_normal"),
	DAMAGE_MAX("damage_max", "damage_normal"),
	BLOCK("block_normal"),
	BLOCK_TINTED("block_tinted", "block_normal"),
	POISON("poison_normal"),
	POISON_TINTED("poison_tinted", "poison_normal"),
	VENOM("venom_normal"),
	VENOM_TINTED("venom_tinted", "venom_normal"),
	DISEASE("disease_normal"),
	DISEASE_TINTED("disease_tinted", "disease_normal"),
	HEAL("heal_normal", "heal", "poison_normal"),
	HEAL_TINTED("heal_tinted", "heal_normal", "heal", "poison_tinted", "poison_normal"),
	CYAN("damage_cyan_normal", "damage_normal"),
	CYAN_TINTED("damage_cyan_tinted", "damage_cyan_normal", "damage_tinted", "damage_normal"),
	CYAN_MAX("damage_cyan_max", "damage_max", "damage_cyan_normal", "damage_normal"),
	ORANGE("damage_orange_normal", "damage_normal"),
	ORANGE_TINTED("damage_orange_tinted", "damage_orange_normal", "damage_tinted", "damage_normal"),
	ORANGE_MAX("damage_orange_max", "damage_max", "damage_orange_normal", "damage_normal"),
	YELLOW("damage_yellow_normal", "damage_normal"),
	YELLOW_TINTED("damage_yellow_tinted", "damage_yellow_normal", "damage_tinted", "damage_normal"),
	YELLOW_MAX("damage_yellow_max", "damage_max", "damage_yellow_normal", "damage_normal"),
	WHITE("damage_white_normal", "damage_normal"),
	WHITE_TINTED("damage_white_tinted", "damage_white_normal", "damage_tinted", "damage_normal"),
	WHITE_MAX("damage_white_max", "damage_max", "damage_white_normal", "damage_normal"),
	POISE("damage_poise_normal", "damage_normal"),
	POISE_TINTED("damage_poise_tinted", "damage_poise_normal", "damage_tinted", "damage_normal"),
	POISE_MAX("damage_poise_max", "damage_max", "damage_poise_normal", "damage_normal"),
	PRAYER_DRAIN("prayer_drain_normal", "damage_normal"),
	BLEED("bleed_normal", "bleed", "damage_normal"),
	BURN("burn_normal", "burn", "poison_normal", "damage_normal"),
	CORRUPTION("corruption_normal", "damage_normal"),
	DOOM("doom_normal", "damage_normal"),
	SANITY_DRAIN("sanity_drain_normal", "damage_normal"),
	SANITY_RESTORE("sanity_restore_normal", "heal_normal", "poison_normal");

	public static final int DAMAGE_MAX_SHORT = 77;
	public static final int DAMAGE_SHORT = 82;

	private final String[] fileNames;

	HitsplatSkin(String... fileNames)
	{
		this.fileNames = fileNames;
	}

	public String[] getFileNames()
	{
		return fileNames;
	}

	public HitsplatSkin untinted()
	{
		switch (this)
		{
			case DAMAGE_TINTED:
				return DAMAGE;
			case BLOCK_TINTED:
				return BLOCK;
			case POISON_TINTED:
				return POISON;
			case VENOM_TINTED:
				return VENOM;
			case DISEASE_TINTED:
				return DISEASE;
			case HEAL_TINTED:
				return HEAL;
			case CYAN_TINTED:
				return CYAN;
			case ORANGE_TINTED:
				return ORANGE;
			case YELLOW_TINTED:
				return YELLOW;
			case WHITE_TINTED:
				return WHITE;
			case POISE_TINTED:
				return POISE;
			default:
				return this;
		}
	}

	public HitsplatSkin tinted()
	{
		switch (this)
		{
			case DAMAGE:
				return DAMAGE_TINTED;
			case BLOCK:
				return BLOCK_TINTED;
			case POISON:
				return POISON_TINTED;
			case VENOM:
				return VENOM_TINTED;
			case DISEASE:
				return DISEASE_TINTED;
			case HEAL:
				return HEAL_TINTED;
			case CYAN:
				return CYAN_TINTED;
			case ORANGE:
				return ORANGE_TINTED;
			case YELLOW:
				return YELLOW_TINTED;
			case WHITE:
				return WHITE_TINTED;
			case POISE:
				return POISE_TINTED;
			default:
				return this;
		}
	}

	public static boolean isBlock(int hitsplatType)
	{
		return hitsplatType == HitsplatID.BLOCK_ME
			|| hitsplatType == HitsplatID.BLOCK_OTHER
			|| hitsplatType == HitsplatID.DISEASE_BLOCKED;
	}

	public static boolean isSupported(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_OTHER:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.BLOCK_ME:
			case HitsplatID.BLOCK_OTHER:
			case HitsplatID.POISON:
			case HitsplatID.VENOM:
			case HitsplatID.DISEASE:
			case HitsplatID.DISEASE_BLOCKED:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.BLEED:
			case HitsplatID.BURN:
			case DAMAGE_MAX_SHORT:
			case DAMAGE_SHORT:
				return true;
			default:
				return false;
		}
	}

	public static HitsplatSkin forType(int hitsplatType, boolean onLocalPlayer)
	{
		switch (hitsplatType)
		{
			case HitsplatID.DAMAGE_ME:
				return DAMAGE;
			case HitsplatID.DAMAGE_MAX_ME:
				return DAMAGE_MAX;
			case DAMAGE_SHORT:
				return DAMAGE;
			case DAMAGE_MAX_SHORT:
				return CYAN_MAX;
			case HitsplatID.BLOCK_ME:
				return BLOCK;
			case HitsplatID.BLOCK_OTHER:
				return BLOCK_TINTED;
			case HitsplatID.DAMAGE_ME_CYAN:
				return CYAN;
			case HitsplatID.DAMAGE_OTHER_CYAN:
				return CYAN_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
				return CYAN_MAX;
			case HitsplatID.CYAN_UP:
			case HitsplatID.CYAN_DOWN:
				return onLocalPlayer ? CYAN : CYAN_TINTED;
			case HitsplatID.DAMAGE_ME_ORANGE:
				return ORANGE;
			case HitsplatID.DAMAGE_OTHER_ORANGE:
				return ORANGE_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
				return ORANGE_MAX;
			case HitsplatID.DAMAGE_ME_YELLOW:
				return YELLOW;
			case HitsplatID.DAMAGE_OTHER_YELLOW:
				return YELLOW_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
				return YELLOW_MAX;
			case HitsplatID.DAMAGE_ME_WHITE:
				return WHITE;
			case HitsplatID.DAMAGE_OTHER_WHITE:
				return WHITE_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
				return WHITE_MAX;
			case HitsplatID.DAMAGE_ME_POISE:
				return POISE;
			case HitsplatID.DAMAGE_OTHER_POISE:
				return POISE_TINTED;
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return POISE_MAX;
			case HitsplatID.POISON:
				return onLocalPlayer ? POISON : POISON_TINTED;
			case HitsplatID.VENOM:
				return onLocalPlayer ? VENOM : VENOM_TINTED;
			case HitsplatID.DISEASE:
				return onLocalPlayer ? DISEASE : DISEASE_TINTED;
			case HitsplatID.DISEASE_BLOCKED:
				return onLocalPlayer ? BLOCK : BLOCK_TINTED;
			case HitsplatID.HEAL:
				return onLocalPlayer ? HEAL : HEAL_TINTED;
			case HitsplatID.PRAYER_DRAIN:
				return PRAYER_DRAIN;
			case HitsplatID.BLEED:
				return BLEED;
			case HitsplatID.BURN:
				return BURN;
			case HitsplatID.CORRUPTION:
				return CORRUPTION;
			case HitsplatID.DOOM:
				return DOOM;
			case HitsplatID.SANITY_DRAIN:
				return SANITY_DRAIN;
			case HitsplatID.SANITY_RESTORE:
				return SANITY_RESTORE;
			case HitsplatID.DAMAGE_OTHER:
			default:
				return DAMAGE_TINTED;
		}
	}
}

package io.mark.hitsplats.art;

import io.mark.hitsplats.combat.CombatStyle;
import io.mark.hitsplats.config.HitsplatIconSet;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.IntConsumer;
import java.util.function.Supplier;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;

@Slf4j
@Singleton
public class HitsplatSprites
{
	private final ScheduledExecutorService executor;

	private static final String RESOURCE_ROOT = "/io/mark/hitsplats/";
	private static final String ICON_DIRECTORY = "style_icons";
	private static final int SHADOW_ALPHA = 120;
	private static final int SUPERSAMPLE = 8;

	private volatile Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> packs;
	private volatile Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> packShadows;
	private volatile Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> icons;
	private volatile Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> iconShadows;
	private volatile Map<HitsplatIconSet, Integer> iconSlotWidths;
	private volatile Map<HitsplatStyle, StyleProperties> styleProperties;

	@Inject
	private HitsplatSprites(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	public void load(int shadowRadius, Supplier<Filepath> overrides, IntConsumer onLoaded)
	{
		executor.execute(() ->
		{
			Overrides overrideRoot = new Overrides(prepareOverrideDirectory(overrides));

			Map<HitsplatStyle, StyleProperties> loadedProperties = new EnumMap<>(HitsplatStyle.class);
			Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loaded = new EnumMap<>(HitsplatStyle.class);
			Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loadedShadows = new EnumMap<>(HitsplatStyle.class);
			for (HitsplatStyle style : HitsplatStyle.values())
			{
				StyleProperties properties = overrideRoot.loadProperties(style);
				loadedProperties.put(style, properties);

				Map<HitsplatSkin, BufferedImage> pack = loadPack(style, properties, overrideRoot);
				loaded.put(style, pack);
				loadedShadows.put(style, outlinePack(pack, shadowRadius, properties));
			}

			Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> loadedIcons = new EnumMap<>(HitsplatIconSet.class);
			Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> loadedIconShadows = new EnumMap<>(HitsplatIconSet.class);
			Map<HitsplatIconSet, Integer> widths = new EnumMap<>(HitsplatIconSet.class);

			for (HitsplatIconSet set : HitsplatIconSet.values())
			{
				Map<CombatStyle, BufferedImage> setIcons = loadIcons(set, overrideRoot);
				Map<CombatStyle, BufferedImage> shadows = new EnumMap<>(CombatStyle.class);
				int widest = 0;

				for (Map.Entry<CombatStyle, BufferedImage> entry : setIcons.entrySet())
				{
					if (shadowRadius > 0)
					{
						shadows.put(entry.getKey(), outline(entry.getValue(), shadowRadius, SHADOW_ALPHA, 0));
					}

					widest = Math.max(widest, entry.getValue().getWidth());
				}

				loadedIcons.put(set, setIcons);
				loadedIconShadows.put(set, shadows);
				widths.put(set, widest);
			}

			iconSlotWidths = widths;
			iconShadows = loadedIconShadows;
			icons = loadedIcons;
			styleProperties = loadedProperties;
			packShadows = loadedShadows;
			packs = loaded;

			onLoaded.accept(overrideRoot.getApplied());
		});
	}

	public void clear()
	{
		packs = null;
		packShadows = null;
		icons = null;
		iconShadows = null;
		iconSlotWidths = null;
		styleProperties = null;
	}

	public StyleProperties getProperties(HitsplatStyle style)
	{
		Map<HitsplatStyle, StyleProperties> loaded = styleProperties;
		StyleProperties properties = loaded == null ? null : loaded.get(style);
		return properties == null ? StyleProperties.defaults(style) : properties;
	}

	public BufferedImage get(HitsplatStyle style, HitsplatSkin skin)
	{
		Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loaded = packs;
		if (loaded == null)
		{
			return null;
		}

		Map<HitsplatSkin, BufferedImage> pack = loaded.get(style);
		return pack == null ? null : pack.get(skin);
	}

	public BufferedImage getShadow(HitsplatStyle style, HitsplatSkin skin)
	{
		Map<HitsplatStyle, Map<HitsplatSkin, BufferedImage>> loaded = packShadows;
		if (loaded == null)
		{
			return null;
		}

		Map<HitsplatSkin, BufferedImage> pack = loaded.get(style);
		return pack == null ? null : pack.get(skin);
	}

	private static Map<HitsplatSkin, BufferedImage> outlinePack(Map<HitsplatSkin, BufferedImage> pack, int shadowRadius,
		StyleProperties properties)
	{
		Map<HitsplatSkin, BufferedImage> shadows = new EnumMap<>(HitsplatSkin.class);
		if (shadowRadius <= 0 || properties.getShadowAlpha() <= 0)
		{
			return shadows;
		}

		// Skins share images through their fallback chains, so outline each distinct one once.
		Map<BufferedImage, BufferedImage> byImage = new IdentityHashMap<>();

		for (Map.Entry<HitsplatSkin, BufferedImage> entry : pack.entrySet())
		{
			shadows.put(entry.getKey(), byImage.computeIfAbsent(entry.getValue(),
				image -> outline(image, shadowRadius, properties.getShadowAlpha(), properties.getShadowRgb())));
		}

		return shadows;
	}

	public BufferedImage getIcon(HitsplatIconSet set, CombatStyle style)
	{
		return lookup(icons, set, style);
	}

	public BufferedImage getIconShadow(HitsplatIconSet set, CombatStyle style)
	{
		return lookup(iconShadows, set, style);
	}

	public int getIconSlotWidth(HitsplatIconSet set)
	{
		Map<HitsplatIconSet, Integer> widths = iconSlotWidths;
		if (widths == null)
		{
			return 0;
		}

		Integer width = widths.get(set);
		return width == null ? 0 : width;
	}

	private static BufferedImage lookup(Map<HitsplatIconSet, Map<CombatStyle, BufferedImage>> loaded,
		HitsplatIconSet set, CombatStyle style)
	{
		if (loaded == null)
		{
			return null;
		}

		Map<CombatStyle, BufferedImage> pack = loaded.get(set);
		return pack == null ? null : pack.get(style);
	}

	private static Map<CombatStyle, BufferedImage> loadIcons(HitsplatIconSet set, Overrides overrideRoot)
	{
		Map<CombatStyle, BufferedImage> pack = new EnumMap<>(CombatStyle.class);
		for (CombatStyle style : CombatStyle.values())
		{
			BufferedImage image = loadImage(overrideRoot, ICON_DIRECTORY + "/" + set.getDirectory(), style.getFileName());
			if (image != null)
			{
				pack.put(style, trim(image));
			}
		}

		log.debug("Loaded {} of {} {} combat style icons", pack.size(), CombatStyle.values().length, set.getDirectory());
		return pack;
	}

	private static Map<HitsplatSkin, BufferedImage> loadPack(HitsplatStyle style, StyleProperties properties,
		Overrides overrideRoot)
	{
		Map<HitsplatSkin, BufferedImage> pack = new EnumMap<>(HitsplatSkin.class);
		Map<String, BufferedImage> byFileName = new HashMap<>();

		for (HitsplatSkin skin : HitsplatSkin.values())
		{
			for (String fileName : skin.getFileNames())
			{
				BufferedImage image;
				if (byFileName.containsKey(fileName))
				{
					image = byFileName.get(fileName);
				}
				else
				{
					image = loadSkin(style, properties, overrideRoot, fileName);
					byFileName.put(fileName, image);
				}

				if (image != null)
				{
					pack.put(skin, image);
					break;
				}
			}
		}

		log.debug("Loaded hitsplat style {}: {} of {} skins", style.getDirectory(), pack.size(), HitsplatSkin.values().length);
		return pack;
	}

	private static BufferedImage outline(BufferedImage image, int radius, int maxAlpha, int rgb)
	{
		int width = image.getWidth() + radius * 2;
		int height = image.getHeight() + radius * 2;
		int[] alpha = new int[width * height];

		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) == 0)
				{
					continue;
				}

				for (int dy = -radius; dy <= radius; dy++)
				{
					for (int dx = -radius; dx <= radius; dx++)
					{
						double distance = Math.sqrt(dx * dx + dy * dy);
						if (distance > radius)
						{
							continue;
						}

						int value = (int) Math.round(maxAlpha * (1d - distance / (radius + 1d)));
						int index = (y + radius + dy) * width + x + radius + dx;
						if (value > alpha[index])
						{
							alpha[index] = value;
						}
					}
				}
			}
		}

		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		for (int index = 0; index < alpha.length; index++)
		{
			if (alpha[index] > 0)
			{
				out.setRGB(index % width, index / width, (alpha[index] << 24) | rgb);
			}
		}

		return out;
	}

	private static BufferedImage scale(BufferedImage image, int percent)
	{
		if (image == null || percent == 100)
		{
			return image;
		}

		int width = Math.max(1, image.getWidth() * percent / 100);
		int height = Math.max(1, image.getHeight() * percent / 100);

		// A whole number of pixels per pixel is already perfect, and nearest neighbour keeps it razor sharp.
		if (percent % 100 == 0)
		{
			return nearest(image, width, height);
		}

		// Anything else lands between pixels. Blowing the art up by a whole number first means every source pixel is
		// still the same size, and averaging that back down to the target spreads the leftovers evenly instead of
		// leaving some rows a pixel fatter than their neighbours.
		BufferedImage supersampled = nearest(image,
			image.getWidth() * SUPERSAMPLE, image.getHeight() * SUPERSAMPLE);

		return average(supersampled, width, height);
	}

	private static BufferedImage nearest(BufferedImage image, int width, int height)
	{
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = out.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(image, 0, 0, width, height, null);
		graphics.dispose();

		return out;
	}

	private static BufferedImage average(BufferedImage image, int width, int height)
	{
		int sourceWidth = image.getWidth();
		int sourceHeight = image.getHeight();
		int[] pixels = image.getRGB(0, 0, sourceWidth, sourceHeight, null, 0, sourceWidth);
		int[] out = new int[width * height];

		for (int y = 0; y < height; y++)
		{
			int fromY = y * sourceHeight / height;
			int toY = Math.max(fromY + 1, (y + 1) * sourceHeight / height);

			for (int x = 0; x < width; x++)
			{
				int fromX = x * sourceWidth / width;
				int toX = Math.max(fromX + 1, (x + 1) * sourceWidth / width);

				long alpha = 0;
				long red = 0;
				long green = 0;
				long blue = 0;
				int count = 0;

				for (int sourceY = fromY; sourceY < toY; sourceY++)
				{
					for (int sourceX = fromX; sourceX < toX; sourceX++)
					{
						int pixel = pixels[sourceY * sourceWidth + sourceX];
						int pixelAlpha = pixel >>> 24;

						// Weighted by alpha, so the transparent pixels around the splat don't drag its edges dark.
						alpha += pixelAlpha;
						red += ((pixel >> 16) & 0xFF) * pixelAlpha;
						green += ((pixel >> 8) & 0xFF) * pixelAlpha;
						blue += (pixel & 0xFF) * pixelAlpha;
						count++;
					}
				}

				int outAlpha = (int) (alpha / count);
				out[y * width + x] = alpha == 0 ? 0 : (outAlpha << 24)
					| ((int) (red / alpha) << 16)
					| ((int) (green / alpha) << 8)
					| (int) (blue / alpha);
			}
		}

		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		scaled.setRGB(0, 0, width, height, out, 0, width);
		return scaled;
	}

	private static BufferedImage trim(BufferedImage image)
	{
		int minX = image.getWidth();
		int minY = image.getHeight();
		int maxX = -1;
		int maxY = -1;

		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) == 0)
				{
					continue;
				}

				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);
			}
		}

		if (maxX < 0 || (minX == 0 && minY == 0 && maxX == image.getWidth() - 1 && maxY == image.getHeight() - 1))
		{
			return image;
		}

		return image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}

	private static Filepath prepareOverrideDirectory(Supplier<Filepath> overrides)
	{
		Filepath root;
		try
		{
			root = overrides.get();
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to open the hitsplat override directory", e);
			return null;
		}

		if (root == null)
		{
			return null;
		}

		for (HitsplatStyle style : HitsplatStyle.values())
		{
			createDirectory(root, style.getDirectory());
		}

		for (HitsplatIconSet set : HitsplatIconSet.values())
		{
			createDirectory(root, ICON_DIRECTORY + "/" + set.getDirectory());
		}

		return root;
	}

	private static void createDirectory(Filepath root, String directory)
	{
		try
		{
			resolve(root, directory).createDirectories();
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unable to create hitsplat override directory {}", directory, e);
		}
	}

	private static Filepath resolve(Filepath root, String directory)
	{
		Filepath path = root;
		for (String segment : directory.split("/"))
		{
			path = path.joinSegment(segment);
		}

		return path;
	}

	private static BufferedImage loadSkin(HitsplatStyle style, StyleProperties properties, Overrides overrideRoot,
		String fileName)
	{
		BufferedImage override = overrideRoot.load(style.getDirectory(), fileName);
		if (override != null)
		{
			// A pack that turns this on has drawn its art at the size it wants it, so leave it exactly as it is.
			return properties.isDisableSplatIconScale() ? override : scale(override, properties.getSize());
		}

		return scale(loadResource(style.getDirectory(), fileName), properties.getSize());
	}

	private static BufferedImage loadImage(Overrides overrideRoot, String directory, String fileName)
	{
		BufferedImage override = overrideRoot.load(directory, fileName);
		return override != null ? override : loadResource(directory, fileName);
	}

	private static BufferedImage loadResource(String directory, String fileName)
	{
		String path = RESOURCE_ROOT + directory + "/" + fileName + ".png";
		if (HitsplatSprites.class.getResource(path) == null)
		{
			return null;
		}

		try
		{
			return ImageUtil.loadImageResource(HitsplatSprites.class, path);
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to read hitsplat image {}", path, e);
			return null;
		}
	}

	private static final class Overrides
	{
		private final Filepath root;
		private int applied;

		private Overrides(Filepath root)
		{
			this.root = root;
		}

		private int getApplied()
		{
			return applied;
		}

		private StyleProperties loadProperties(HitsplatStyle style)
		{
			if (root == null)
			{
				return StyleProperties.defaults(style);
			}

			Filepath path;
			try
			{
				path = resolve(root, style.getDirectory()).joinSegment(StyleProperties.FILE_NAME);
				if (!path.isFile())
				{
					return StyleProperties.defaults(style);
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Unable to resolve hitsplat style properties for {}", style.getDirectory(), e);
				return StyleProperties.defaults(style);
			}

			try (Reader reader = path.openReader())
			{
				Properties properties = new Properties();
				properties.load(reader);

				log.debug("Using hitsplat style properties {}", path);
				applied++;
				return StyleProperties.read(style, properties);
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Unable to read hitsplat style properties {}", path, e);
				return StyleProperties.defaults(style);
			}
		}

		private BufferedImage load(String directory, String fileName)
		{
			if (root == null)
			{
				return null;
			}

			Filepath path;
			try
			{
				path = resolve(root, directory).joinSegment(fileName + ".png");
				if (!path.isFile())
				{
					return null;
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Unable to resolve hitsplat override {}/{}", directory, fileName, e);
				return null;
			}

			try (InputStream in = path.openInputStream())
			{
				BufferedImage image = ImageIO.read(in);
				if (image == null)
				{
					log.debug("Hitsplat override {} is not an image", path);
					return null;
				}

				log.debug("Using hitsplat override {}", path);
				applied++;
				return toArgb(image);
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Unable to read hitsplat override {}", path, e);
				return null;
			}
		}
	}

	private static BufferedImage toArgb(BufferedImage image)
	{
		if (image.getType() == BufferedImage.TYPE_INT_ARGB)
		{
			return image;
		}

		BufferedImage out = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = out.createGraphics();
		graphics.drawImage(image, 0, 0, null);
		graphics.dispose();
		return out;
	}
}

