package io.mark.hitsplats.art;

import java.awt.Color;
import java.util.Properties;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Getter
public class StyleProperties
{
	public static final String FILE_NAME = "style.properties";

	private static final int DEFAULT_SHADOW_ALPHA = 120;

	private final int size;
	private final boolean disableSplatIconScale;
	private final int textOffsetY;
	private final Color textColor;
	private final Color textShadowColor;
	private final int shadowRgb;
	private final int shadowAlpha;

	private StyleProperties(int size, boolean disableSplatIconScale, int textOffsetY, Color textColor,
		Color textShadowColor, int shadowRgb, int shadowAlpha)
	{
		this.size = size;
		this.disableSplatIconScale = disableSplatIconScale;
		this.textOffsetY = textOffsetY;
		this.textColor = textColor;
		this.textShadowColor = textShadowColor;
		this.shadowRgb = shadowRgb;
		this.shadowAlpha = shadowAlpha;
	}

	public static StyleProperties defaults(HitsplatStyle style)
	{
		return new StyleProperties(style.getScale(), style.isDisableScale(), style.getTextOffsetY(),
			Color.WHITE, Color.BLACK, 0, DEFAULT_SHADOW_ALPHA);
	}

	public static StyleProperties read(HitsplatStyle style, Properties properties)
	{
		StyleProperties defaults = defaults(style);

		return new StyleProperties(
			readInt(properties, "size", defaults.size, 10, 400),
			readBoolean(properties, "disableSplatIconScale", defaults.disableSplatIconScale),
			readInt(properties, "textOffsetY", defaults.textOffsetY, -32, 32),
			readColor(properties, "textColor", defaults.textColor),
			readColor(properties, "textShadowColor", defaults.textShadowColor),
			readColor(properties, "shadowColor", Color.BLACK).getRGB() & 0xFFFFFF,
			readInt(properties, "shadowAlpha", defaults.shadowAlpha, 0, 255));
	}

	private static boolean readBoolean(Properties properties, String key, boolean fallback)
	{
		String value = properties.getProperty(key);
		if (value == null)
		{
			return fallback;
		}

		String trimmed = value.trim();
		if ("true".equalsIgnoreCase(trimmed))
		{
			return true;
		}

		if ("false".equalsIgnoreCase(trimmed))
		{
			return false;
		}

		log.debug("Hitsplat style property {} is not true or false: {}", key, value);
		return fallback;
	}

	private static int readInt(Properties properties, String key, int fallback, int min, int max)
	{
		String value = properties.getProperty(key);
		if (value == null)
		{
			return fallback;
		}

		try
		{
			return Math.max(min, Math.min(max, Integer.parseInt(value.trim())));
		}
		catch (NumberFormatException e)
		{
			log.debug("Hitsplat style property {} is not a number: {}", key, value);
			return fallback;
		}
	}

	private static Color readColor(Properties properties, String key, Color fallback)
	{
		String value = properties.getProperty(key);
		if (value == null)
		{
			return fallback;
		}

		String hex = value.trim();
		if (hex.startsWith("#"))
		{
			hex = hex.substring(1);
		}

		try
		{
			long rgb = Long.parseLong(hex, 16);
			return new Color((int) rgb, hex.length() > 6);
		}
		catch (NumberFormatException e)
		{
			log.debug("Hitsplat style property {} is not a colour: {}", key, value);
			return fallback;
		}
	}
}

package io.mark.hitsplats.combat;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum CombatStyle
{
	MELEE("meele"),
	RANGED("range"),
	MAGIC("magic"),
	CANNON("cannon"),
	DEFENCE("defence");

	private final String fileName;
}

package io.mark.hitsplats.combat;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Projectile;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

@Singleton
public class CombatStyleResolver
{
	private static final int MATCH_WINDOW_CYCLES = 40;
	private static final int PRUNE_AFTER_CYCLES = 30;

	private static final CombatStyle UNATTRIBUTED_PROJECTILE_STYLE = CombatStyle.MAGIC;

	private final ItemManager itemManager;
	private final CombatStyleTables tables;
	private final List<InFlight> inFlight = new ArrayList<>();

	@Inject
	private CombatStyleResolver(ItemManager itemManager, CombatStyleTables tables)
	{
		this.itemManager = itemManager;
		this.tables = tables;
	}

	public void onProjectileMoved(Projectile projectile)
	{
		for (InFlight seen : inFlight)
		{
			if (seen.projectile == projectile && seen.startCycle == projectile.getStartCycle())
			{
				return;
			}
		}

		inFlight.add(new InFlight(projectile, projectile.getStartCycle(), projectile.getEndCycle(),
			projectile.getTargetActor(), styleOf(projectile)));
	}

	public CombatStyle resolve(Actor target, int cycle)
	{
		prune(cycle);

		CombatStyle style = CombatStyle.MELEE;
		int closest = Integer.MAX_VALUE;

		for (InFlight seen : inFlight)
		{
			if (seen.target != target)
			{
				continue;
			}

			int delta = Math.abs(cycle - seen.endCycle);
			if (delta <= MATCH_WINDOW_CYCLES && delta < closest)
			{
				closest = delta;
				style = seen.style;
			}
		}

		return style;
	}

	public void clear()
	{
		inFlight.clear();
	}

	private void prune(int cycle)
	{
		for (Iterator<InFlight> it = inFlight.iterator(); it.hasNext(); )
		{
			if (cycle - it.next().endCycle > PRUNE_AFTER_CYCLES)
			{
				it.remove();
			}
		}
	}

	private CombatStyle styleOf(Projectile projectile)
	{
		if (isCannonball(projectile.getId()))
		{
			return CombatStyle.CANNON;
		}

		CombatStyle projectileStyle = tables.forProjectile(projectile.getId());
		if (projectileStyle != null)
		{
			return projectileStyle;
		}

		Actor source = projectile.getSourceActor();
		if (source == null)
		{
			return UNATTRIBUTED_PROJECTILE_STYLE;
		}

		if (source instanceof Player)
		{
			CombatStyle weaponStyle = weaponStyle((Player) source);
			if (weaponStyle == CombatStyle.RANGED)
			{
				return CombatStyle.RANGED;
			}

			if (weaponStyle == CombatStyle.MAGIC)
			{
				return CombatStyle.MAGIC;
			}
		}

		CombatStyle animationStyle = tables.forAnimation(source.getAnimation());
		if (animationStyle == CombatStyle.RANGED || animationStyle == CombatStyle.MAGIC)
		{
			return animationStyle;
		}

		return UNATTRIBUTED_PROJECTILE_STYLE;
	}

	private CombatStyle weaponStyle(Player player)
	{
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null)
		{
			return null;
		}

		int weaponId = composition.getEquipmentId(KitType.WEAPON);
		if (weaponId <= 0)
		{
			return null;
		}

		ItemStats stats = itemManager.getItemStats(weaponId);
		if (stats == null || stats.getEquipment() == null)
		{
			return null;
		}

		ItemEquipmentStats equipment = stats.getEquipment();
		int melee = Math.max(equipment.getAstab(), Math.max(equipment.getAslash(), equipment.getAcrush()));

		if (equipment.getArange() > melee && equipment.getArange() >= equipment.getAmagic())
		{
			return CombatStyle.RANGED;
		}

		if (equipment.getAmagic() > melee)
		{
			return CombatStyle.MAGIC;
		}

		return CombatStyle.MELEE;
	}

	private static boolean isCannonball(int projectileId)
	{
		return projectileId == SpotanimID.CANNONBALL_TRAVEL
			|| projectileId == SpotanimID.CANNONBALL_TRAVEL_GRANITE
			|| projectileId == SpotanimID.CANNONBALL_TRAVEL_LEAGUE
			|| projectileId == SpotanimID.CANNONBALL_TRAVEL_GRANITE_LEAGUE;
	}

	private static class InFlight
	{
		private final Projectile projectile;
		private final int startCycle;
		private final int endCycle;
		private final Actor target;
		private final CombatStyle style;

		private InFlight(Projectile projectile, int startCycle, int endCycle, Actor target, CombatStyle style)
		{
			this.projectile = projectile;
			this.startCycle = startCycle;
			this.endCycle = endCycle;
			this.target = target;
			this.style = style;
		}
	}
}

package io.mark.hitsplats.combat;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class CombatStyleTables
{
	private static final String ANIMATION_RESOURCE = "/io/mark/hitsplats/attack_animations.tsv";
	private static final String PROJECTILE_RESOURCE = "/io/mark/hitsplats/projectile_styles.tsv";

	private final ScheduledExecutorService executor;
	private volatile Map<Integer, CombatStyle> animations = Collections.emptyMap();
	private volatile Map<Integer, CombatStyle> projectiles = Collections.emptyMap();

	@Inject
	private CombatStyleTables(ScheduledExecutorService executor)
	{
		this.executor = executor;
	}

	public void load()
	{
		executor.execute(() ->
		{
			animations = read(ANIMATION_RESOURCE);
			projectiles = read(PROJECTILE_RESOURCE);
		});
	}

	public void clear()
	{
		animations = Collections.emptyMap();
		projectiles = Collections.emptyMap();
	}

	public CombatStyle forAnimation(int animationId)
	{
		return animationId == -1 ? null : animations.get(animationId);
	}

	public CombatStyle forProjectile(int projectileId)
	{
		return projectiles.get(projectileId);
	}

	private static Map<Integer, CombatStyle> read(String resource)
	{
		Map<Integer, CombatStyle> parsed = new HashMap<>();

		InputStream in = CombatStyleTables.class.getResourceAsStream(resource);
		if (in == null)
		{
			log.warn("Missing combat style table {}", resource);
			return parsed;
		}

		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.charAt(0) == '#')
				{
					continue;
				}

				String[] parts = line.split("\t");
				if (parts.length < 2)
				{
					continue;
				}

				parsed.put(Integer.parseInt(parts[0]), CombatStyle.valueOf(parts[1]));
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to read combat style table {}", resource, e);
		}

		log.debug("Loaded {} rows from {}", parsed.size(), resource);
		return parsed;
	}
}

