package io.mark.hitsplats.heal;

import java.util.Arrays;
import javax.inject.Singleton;

@Singleton
public class HealTracker
{
	public static final int BELOW_POSITION = 4;

	private static final int SLOTS = 4;
	private static final int DISPLAY_CYCLES = 70;

	private final HealSplat[] positions = new HealSplat[SLOTS + 1];

	public void add(int cycle, int busySlots, int amount, int itemId)
	{
		int position = BELOW_POSITION;
		for (int slot = 0; slot < SLOTS; slot++)
		{
			HealSplat sitting = positions[slot];
			if ((busySlots & (1 << slot)) == 0 && (sitting == null || sitting.getEndCycle() <= cycle))
			{
				position = slot;
				break;
			}
		}

		positions[position] = new HealSplat(position, cycle + DISPLAY_CYCLES, String.valueOf(amount), itemId);
	}

	public void vacate(int slot)
	{
		if (slot < 0 || slot >= SLOTS)
		{
			return;
		}

		HealSplat sitting = positions[slot];
		if (sitting == null)
		{
			return;
		}

		positions[slot] = null;

		HealSplat below = positions[BELOW_POSITION];
		if (below != null && below.getEndCycle() > sitting.getEndCycle())
		{
			return;
		}

		sitting.setPosition(BELOW_POSITION);
		positions[BELOW_POSITION] = sitting;
	}

	public void prune(int cycle)
	{
		for (int i = 0; i < positions.length; i++)
		{
			HealSplat splat = positions[i];
			if (splat != null && splat.getEndCycle() <= cycle)
			{
				positions[i] = null;
			}
		}
	}

	public HealSplat[] getPositions()
	{
		return positions;
	}

	public boolean isEmpty()
	{
		for (HealSplat splat : positions)
		{
			if (splat != null)
			{
				return false;
			}
		}

		return true;
	}

	public void clear()
	{
		Arrays.fill(positions, null);
	}
}

package io.mark.hitsplats.hit;

import io.mark.hitsplats.art.HitsplatSkin;
import io.mark.hitsplats.combat.CombatStyle;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Actor;

@Singleton
public class HitsplatTracker
{
	private static final int MAX_SLOTS = 4;

	private final Map<Actor, List<TrackedHitsplat>> tracked = new HashMap<>();

	public int add(Actor actor, int cycle, int endCycle, HitsplatSkin skin, CombatStyle combatStyle, String text, boolean block)
	{
		List<TrackedHitsplat> splats = tracked.computeIfAbsent(actor, a -> new ArrayList<>(MAX_SLOTS));

		boolean full = splats.size() >= MAX_SLOTS;
		int cursor = 0;
		for (int i = 0; i < splats.size(); i++)
		{
			if (splats.get(i).getEndCycle() > cycle)
			{
				cursor = (i + 1) % MAX_SLOTS;
			}
			else
			{
				full = false;
			}
		}

		int slot = -1;
		if (full)
		{
			int earliest = Integer.MAX_VALUE;
			for (int i = 0; i < splats.size(); i++)
			{
				if (splats.get(i).getEndCycle() < earliest)
				{
					earliest = splats.get(i).getEndCycle();
					slot = i;
				}
			}
		}
		else
		{
			for (int attempt = 0; attempt < MAX_SLOTS; attempt++)
			{
				int index = cursor;
				cursor = (cursor + 1) % MAX_SLOTS;

				if (index >= splats.size())
				{
					splats.add(null);
					slot = splats.size() - 1;
					break;
				}

				if (splats.get(index).getEndCycle() <= cycle)
				{
					slot = index;
					break;
				}
			}
		}

		if (slot < 0)
		{
			return -1;
		}

		splats.set(slot, new TrackedHitsplat(slot, endCycle, skin, combatStyle, text, block));
		return slot;
	}

	public int busySlots(Actor actor, int cycle, int fadeLength)
	{
		List<TrackedHitsplat> splats = tracked.get(actor);
		if (splats == null)
		{
			return 0;
		}

		int mask = 0;
		for (int i = 0; i < splats.size(); i++)
		{
			TrackedHitsplat splat = splats.get(i);
			if (splat != null && splat.getEndCycle() + fadeLength > cycle)
			{
				mask |= 1 << splat.getSlot();
			}
		}

		return mask;
	}

	public void remove(Actor actor)
	{
		tracked.remove(actor);
	}

	public void clear()
	{
		tracked.clear();
	}

	public Map<Actor, List<TrackedHitsplat>> getTracked()
	{
		return tracked;
	}
}

